add(1995,4,4,'The exceptional x=1 case must be separated; parity-sensitive consecutive-square bounds then isolate x=3.', 'A geometric sum that is a square',r'Find all positive integer pairs $(x,y)$ satisfying $y^2(x-1)=x^5-1$.',r'For $x=1$, every positive $y$ works. For $x>1$, put $F=x^4+x^3+x^2+x+1=y^2$. If $x$ is even, $F$ lies strictly between $(x^2+x/2)^2$ and $(x^2+x/2+1)^2$: the respective differences are $3x^2/4+x+1>0$ and $5x^2/4>0$. If $x$ is odd and $x>3$, it lies strictly between $(x^2+(x-1)/2)^2$ and $(x^2+(x+1)/2)^2$; the upper difference is $(x-3)(x+1)/4>0$, and the lower difference is positive. The only remaining value $x=3$ gives $y=11$. Thus the answers are $(1,y)$ for all positive $y$, and $(3,11)$.','Number Theory',['Diophantine equations','Consecutive squares','Parity'])
add(1995,5,1.5,'Completing the square turns the region into a disk; uniqueness means a tangent line at distance equal to its radius.')
add(1995,6,3,'Taking n to be a power of two and repeatedly squaring over the field with two elements leaves exactly three nonzero coefficients.')
add(1995,7,4,'Ceva supplies a product of ratios, which must be translated through a parallel line into the required midpoint relation.','A parallel through a cevian foot',r'Concurrent cevians $AK,BL,CM$ of triangle $ABC$ meet the opposite sides at $K,L,M$. The line through $M$ parallel to $KL$ meets $BC$ at $V$ and $AK$ at $W$. Prove that $VM=MW$.',r'Use affine coordinates $A=(0,1),B=(0,0),C=(1,0)$ and write $K=(k,0),L=(l,1-l),M=(0,m)$. Ceva gives $k(1-l)(1-m)=lm(1-k)$, hence $k(1-l-m+2lm)=lm$. The line through $M$ parallel to $KL$ has parametrisation $(t(l-k),m+t(1-l))$. Its intersection with $BC$ has parameter $-m/(1-l)$. At the opposite parameter $m/(1-l)$, the coordinates satisfy $x/k+y=1$ by the displayed Ceva identity, so this point is $W$. Thus $M$ is the midpoint of $VW$.','Geometry',['Ceva','Coordinates','Midpoints','Parallel lines'])
add(1995,8,4,'The substitution y=1 yields cube-root invariance; combining it with multiplicativity and positivity excludes both zero and negative values.','A functional equation with cube roots',r'Determine all functions $f:(0,\infty)\to\mathbb R$ such that $f(1)=1/2$ and $f(xy)=f(x)f(\sqrt[3]{y})+f(y)f(\sqrt[3]{x})$ for positive $x,y$.',r'Setting $y=1$ gives $f(\sqrt[3]{x})=f(x)$. Thus $g=2f$ satisfies $g(xy)=g(x)g(y)$, $g(1)=1$, and $g(\sqrt[3]{x})=g(x)$. Therefore $g(x)^3=g(x)$. Also $g(x)g(1/x)=1$, so $g(x)\ne0$, while $g(x)=g(\sqrt{x})^2>0$. Hence $g(x)=1$ for every positive $x$. The unique solution is $f(x)=1/2$, which directly satisfies the equation.','Algebra',['Functional equations','Multiplicativity','Radicals'])
